import React, { useEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";

const subtitles = [
  "Explore, analyze, and visualize mental health data.",
  "Your secure, cloud-powered data platform.",
  "Collaborate and discover new insights!"
];

function useTypewriter(texts, speed = 40, pause = 1200) {
  const [displayed, setDisplayed] = useState("");
  const [index, setIndex] = useState(0);
  const [char, setChar] = useState(0);
  const timeout = useRef();

  useEffect(() => {
    if (char < texts[index].length) {
      timeout.current = setTimeout(() => setChar(char + 1), speed);
      setDisplayed(texts[index].slice(0, char + 1));
    } else {
      timeout.current = setTimeout(() => {
        setChar(0);
        setIndex((index + 1) % texts.length);
      }, pause);
    }
    return () => clearTimeout(timeout.current);
  }, [char, index, texts, speed, pause]);

  return displayed;
}

export default function Home() {
  const subtitle = useTypewriter(subtitles);
  return (
    <main className="flex flex-col min-h-screen relative overflow-hidden">
      {/* Animated Gradient Background */}
      <div className="absolute inset-0 -z-10 animate-gradient bg-gradient-to-tr from-purple-200 via-blue-100 to-pink-100" />
      {/* Floating Icon */}
      <div className="absolute left-1/2 top-24 -translate-x-1/2 animate-bounce-slow">
        <svg width="48" height="48" fill="none" viewBox="0 0 48 48">
          <circle cx="24" cy="24" r="22" fill="#a78bfa" fillOpacity="0.2" />
          <path d="M24 14v14m0 0l-6-6m6 6l6-6" stroke="#a78bfa" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
      </div>
      {/* Navbar */}
      <nav className="w-full bg-white shadow flex items-center justify-between px-8 py-4 mb-8">
        <div className="text-2xl font-bold text-purple-700 tracking-tight">Data Commons</div>
        <div className="space-x-6">
          <Link to="/" className="text-gray-700 hover:text-purple-700 transition-colors">Home</Link>
          <Link to="/dashboard" className="text-gray-700 hover:text-purple-700 transition-colors">Dashboard</Link>
          <Link to="/upload" className="text-gray-700 hover:text-purple-700 transition-colors">Upload</Link>
          <Link to="/login" className="text-gray-700 hover:text-purple-700 transition-colors">Login</Link>
        </div>
      </nav>
      {/* Hero/Card */}
      <section className="flex-1 flex items-center justify-center py-12 px-4">
        <div className="bg-white/90 backdrop-blur rounded-3xl shadow-2xl p-10 w-full max-w-2xl text-center transition-all duration-500 ease-in-out opacity-0 animate-fade-in">
          <h1 className="text-5xl md:text-6xl font-extrabold mb-4 text-gray-900 leading-tight">Welcome to the Data Commons</h1>
          <p className="mb-8 text-xl md:text-2xl text-gray-500 font-medium min-h-[2.5em]">
            {subtitle}
            <span className="inline-block w-2 h-6 align-middle bg-purple-400 animate-blink ml-1 rounded"></span>
          </p>
          <Link
            to="/login"
            className="inline-block bg-purple-600 text-white px-8 py-3 rounded-lg text-lg font-semibold shadow hover:bg-purple-700 transition-all duration-200 transform hover:scale-105 focus:outline-none focus:ring-2 focus:ring-purple-400"
          >
            Get Started
          </Link>
        </div>
      </section>
    </main>
  );
}

